package jp.wakeguard.alarm;
import android.appwidget.*;import android.content.*;import android.os.SystemClock;import android.widget.RemoteViews;
public class TimerWidgetProvider extends AppWidgetProvider{
 static void update(Context c,AppWidgetManager m,int id){RemoteViews r=new RemoteViews(c.getPackageName(),R.layout.widget_timer);TimerStore.Entry e=TimerStore.firstRunning(c);if(e==null){for(TimerStore.Entry x:TimerStore.all(c))if(x.remainingMs>0){e=x;break;}}if(e==null){r.setTextViewText(R.id.timer_name,I18n.tr(c,"タイマーなし"));r.setTextViewText(R.id.timer_static,"00:00");r.setViewVisibility(R.id.timer_static,android.view.View.VISIBLE);r.setViewVisibility(R.id.timer_chrono,android.view.View.GONE);r.setTextViewText(R.id.timer_toggle,I18n.tr(c,"開く"));r.setOnClickPendingIntent(R.id.timer_toggle,WidgetSuite.open(c,ClockActivity.class,"mode","timer",25000+id));}else{String label=e.label==null||e.label.isEmpty()?I18n.tr(c,"タイマー"):e.label;r.setTextViewText(R.id.timer_name,label);if(e.running){long base=SystemClock.elapsedRealtime()+e.remaining();r.setChronometer(R.id.timer_chrono,base,null,true);if(android.os.Build.VERSION.SDK_INT>=24)r.setChronometerCountDown(R.id.timer_chrono,true);r.setViewVisibility(R.id.timer_static,android.view.View.GONE);r.setViewVisibility(R.id.timer_chrono,android.view.View.VISIBLE);r.setTextViewText(R.id.timer_toggle,I18n.tr(c,"一時停止"));}else{r.setTextViewText(R.id.timer_static,WidgetSuite.fmtTimer(e.remainingMs));r.setViewVisibility(R.id.timer_static,android.view.View.VISIBLE);r.setViewVisibility(R.id.timer_chrono,android.view.View.GONE);r.setTextViewText(R.id.timer_toggle,I18n.tr(c,"再開"));}r.setOnClickPendingIntent(R.id.timer_toggle,WidgetSuite.action(c,WidgetActionReceiver.TIMER_TOGGLE,e.id,25100+id));r.setOnClickPendingIntent(R.id.timer_plus,WidgetSuite.action(c,WidgetActionReceiver.TIMER_PLUS,e.id,25200+id));}r.setOnClickPendingIntent(R.id.widget_root,WidgetSuite.open(c,ClockActivity.class,"mode","timer",25300+id));m.updateAppWidget(id,r);}public void onUpdate(Context c,AppWidgetManager m,int[] ids){for(int id:ids)update(c,m,id);}public void onAppWidgetOptionsChanged(Context c,AppWidgetManager m,int id,android.os.Bundle b){update(c,m,id);}}
